mapper.update:
update warehouse_record
status = #{status}, del_flag = #{delFlag}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select wr.*, w.name as warehouse_name, s.name as staff_name, (select string_agg(m.name, ',') from warehouse_material wm left join material m on wm.material_id = m.id where wm.warehouse_record_id = wr.id) as material_names from warehouse_record wr left join warehouse w on wr.warehouse_id = w.id left join staff s on wr.staff_id = s.id where wr.del_flag = 0
and wr.warehouse_id = #{warehouseId}
and wr.source like concat('%', #{source}, '%')
and wr.status = #{status}
and wr.warehouse_time >= #{startTime}
and wr.warehouse_time <= #{endTime}
order by wr.create_time desc
